/* eslint-disable */
import request from 'umi-request';
// @ts-ignore
import {getUrl} from './getMsdvBackendURL.ts'

const url = getUrl();

/** list GET /antipatternInfo/list */
export async function listUsingGet(
    // 叠加生成的Param类型 (非body参数swagger默认没有生成对象)
    params: API.listUsingGETParams,
    options?: { [key: string]: any },
) {
    return request<API.BaseResponseListAntipatternInfoVO>(url + '/antipatternInfo/list', {
        method: 'GET',
        params: {
            ...params,
        },
        ...(options || {}),
    });
}

